	// Only the command word is case-insensitive; arguments (a context name,
	// for instance) keep the case the user typed.
	parts := strings.Fields(strings.TrimPrefix(strings.TrimSpace(input), ":"))
	if len(parts) == 0 {
		return Command{Type: CommandUnknown}
	}

	mainCmd, args := strings.ToLower(parts[0]), parts[1:]
	if full, isAlias := actionAliases[mainCmd]; isAlias {
		mainCmd = full
	}

	if action, ok := actionNames[mainCmd]; ok {
		if action == CommandQuit {
			return Command{Type: CommandQuit}
		}
		return Command{Type: action, Args: args}
	}

	if view, ok := resolveView(mainCmd); ok {
		return Command{Type: CommandView, View: view}
	}

	return Command{Type: CommandUnknown}
}"},{"rank":5,"score":37.9525,"file_path":"internal/scan/kubeconform.go","start_line":260,"end_line":293,"focus_line":263,"snippet_start_line":263,"snippet_end_line":293,"symbol_start_line":263,"symbol_end_line":293,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/scan/kubeconform.go:method:Scanner.runKubeconformStage","symbol_name":"runKubeconformStage","qualified_name":"Scanner.runKubeconformStage","signature":"func (s *Scanner) runKubeconformStage(ctx context.Context, target string, result *Result, mu *sync.Mutex, notify func(ProgressUpdate))","signals":["path","body","symbol-name","graph:callers","complete-symbol"],"snippet":"func (s *Scanner) runKubeconformStage(ctx context.Context, target string, result *Result, mu *sync.Mutex, notify func(ProgressUpdate)) {
	const stage, label = "k8s-schema", "Kubernetes schema"
	notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning})
	progressFn := func(detail string) {
		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning, Detail: detail})
	}
	report, err := RunKubeconform(ctx, target, s.spec(ToolKubeconform), s.kubeconformOptions(), progressFn)

	mu.Lock()
	defer mu.Unlock()
	if err != nil {
		recordStageError(result, "kubeconform", err)
		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageError, Detail: err.Error()})
		return
	}
	if report.SkippedCustom > 0 {
		log.Printf("[scan/kubeconform] %s: %d custom resources not validated (their schema is in a CRD)", target, report.SkippedCustom)
	}
	if len(report.Unrendered) > 0 {
		log.Printf("[scan/kubeconform] %s: not rendered, so not validated: %s", target, strings.Join(report.Unrendered, ", "))
	}
	result.K8sUnrendered = report.Unrendered
	result.Findings = append(result.Findings, report.Findings...)
	// Schema validation is the second half of the Misconfiguration category, so
	// a run of it makes the verdict known on its own: a repository scanned with
	// Trivy's rules switched off but kubeconform on has been looked at, and a
	// "-" there would say otherwise. What the stage could not render is carried
	// in K8sUnrendered and comes back out as the column's "?".
	result.MisconfigScanned = true
	notify(ProgressUpdate{Stage: stage, Label: label, Status: StageDone})
}"},{"rank":6,"score":37.9425,"file_path":"internal/scan/scanner.go","start_line":487,"end_line":495,"focus_line":487,"snippet_start_line":487,"snippet_end_line":488,"symbol_start_line":487,"symbol_end_line":495,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/scan/scanner.go:method:Scanner.spec","symbol_name":"spec","qualified_name":"Scanner.spec","signature":"func (s *Scanner) spec(id ToolID) ToolSpec","signals":["graph:calls","graph:outgoing","graph:callers"],"snippet":"func (s *Scanner) spec(id ToolID) ToolSpec {
