102	func buildTrivyArgs(target string, targetType TargetType, licenseMode bool, tool ToolSpec,
103		server string, ignoreUnfixed, ignoreEOL, remoteImage bool) (toolCmd, error) {
104		server, err := serverAddr(server)
105		if err != nil {
106			return toolCmd{}, err
107		}
108	
109		var args []string
110	
111		switch targetType {
112		case TargetDirectory:
113			args = []string{"fs", "--format", "json"}
114			if licenseMode {
115				args = append(args, "--scanners", "license")
116			} else {
117				args = append(args, "--scanners", "vuln")
118			}
119		case TargetImage:
120			// --scanners vuln explicitly: Trivy's default for an image is
121			// "vuln,secret", so this stage was running the secret scanner on every
122			// image scan and throwing its output away. Secrets are the secret
123			// stage's job, and asking for them twice would report each one twice.
124			args = []string{"image", "--format", "json", "--scanners", "vuln"}
125			if remoteImage {
126				args = append(args, "--image-src", "remote")
127			}
128		default:
129			return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
130		}
131	
132		if server != "" {
133			args = append(args, "--server", server)
134		}
135		if ignoreUnfixed {
136			args = append(args, "--ignore-unfixed")
137		}
138		if ignoreEOL {
139			args = append(args, "--ignore-status", "end_of_life")
140		}
141	
142		return wrapTrivy(args, target, targetType, tool, server, remoteImage), nil
143	}
