204	// wrapTrivy turns tool arguments into the invocation to run: either trivy
205	// directly, or docker run with the target mounted and the tool arguments
206	// appended after the image.
207	//
208	// noSocket says the scan reads its image from the registry, so the engine
209	// socket is not mounted: nothing would use it.
210	//
211	// The user's arguments and --config go right after the subcommand. A
212	// trivy.yaml that sets format: would otherwise break the parsing, and Trivy
213	// lets the command line win over its file — so DevDesk's --format json, which
214	// comes later, stands.
215	func wrapTrivy(args []string, target string, targetType TargetType, tool ToolSpec, server string, noSocket bool) toolCmd {
216		user := tool.Args
217		if tool.Config != "" {
218			path := tool.Config
219			if tool.Source == ToolSourceContainer {
220				path = trivyConfigMount
221			}
222			user = append([]string{"--config", path}, user...)
223		}
224		args = afterSubcommand(args, user)
225	
226		if tool.Source != ToolSourceContainer {
227			return toolCmd{Name: trivyBinary(tool), Args: append(args, target)}
228		}
229	
230		engineArgs := []string{"run", "--rm"}
231		if tool.Config != "" {
232			engineArgs = append(engineArgs, "-v", tool.Config+":"+trivyConfigMount+":ro")
233		}
234		if targetType == TargetDirectory {
235			engineArgs = append(engineArgs, "-v", target+":"+containerScanPath+":ro")
236			args = append(args, containerScanPath)
237		} else {
238			if server == "" && !noSocket {
239				if mount, ok := socketMount(tool.HostSocket); ok {
240					engineArgs = append(engineArgs, "-v", mount)
241				}
242			}
243			args = append(args, target)
244		}
245		engineArgs = append(engineArgs, trivyImage(tool.Image))
246		return toolCmd{Name: engine.Current().Binary, Args: append(engineArgs, args...)}
247	}
